import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, {n} integers a_1, a_2, ..., a_{n} are arranged in a nondecreasing sequence with a_1 = {low} and a_{n} = {high}. Each step is bounded: for every i, a_{i+1} - a_i is an integer in [0, {max_step}]. Define F = (a_1^2 + a_2^2 + ... + a_{n}^2) - {lambda_weight}(a_1a_2 + a_2a_3 + ... + a_{n-1}a_{n}) - (a_1a_3 + a_2a_4 + ... + a_{n-2}a_{n}). Find the minimal possible value of F.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Randomly generate parameters ensuring feasibility and nontriviality
# We aim for moderately large n, range >= 35, and max_step in {2,3,4}
tries = 0
while True:
    n = rng.randint(60, 120)
    low = rng.randint(1, 6)
    rng_range = rng.randint(35, 65)
    high = low + rng_range
    max_step = rng.randint(2, 4)
    lambda_weight = rng.choice([1, 2])
    if rng_range <= max_step * (n - 1) and n >= 5:
        return {
            'n': n,
            'low': low,
            'high': high,
            'max_step': max_step,
            'lambda_weight': lambda_weight
        }
    tries += 1
    if tries > 1000:
        # Fallback: deterministically repair to ensure feasibility
        # Adjust n to the minimal feasible value with a safety margin
        n = (rng_range + max_step - 1) // max_step + 1
        if n < 5:
            n = 5
        return {
            'n': n,
            'low': low,
            'high': high,
            'max_step': max_step,
            'lambda_weight': lambda_weight
        }

    def verifier(assign):
# Validate domain and compute the minimal value via dynamic programming.
# The objective F has only local interactions up to lag 2, so a DP over the last two values suffices.
try:
    n = int(assign['n'])
    low = int(assign['low'])
    high = int(assign['high'])
    max_step = int(assign['max_step'])
    lambda_weight = int(assign['lambda_weight'])
except Exception:
    # Missing or malformed fields
    return False, None  # invalid input

# Basic validations enforcing both correctness and nontrivial difficulty
if not (isinstance(n, int) and isinstance(low, int) and isinstance(high, int) and isinstance(max_step, int) and isinstance(lambda_weight, int)):
    return False, None  # types must be integers
if n < 5:
    # Need enough length to make lag-2 term non-empty and problem nontrivial
    return False, None
if low >= high:
    return False, None
if max_step < 2 or max_step > 10:
    # Bound max_step to keep transitions modest and DP tractable
    return False, None
if lambda_weight <= 0 or lambda_weight > 5:
    return False, None
rng_range = high - low
if rng_range < 30:
    # Ensure nontrivial range so the sequence can't trivially be constant
    return False, None
if rng_range > max_step * (n - 1):
    # Infeasible to reach high under step bound
    return False, None

R = rng_range
INF = 10**100
# dp[xidx][yidx] = minimal cost after setting a_1..a_t, with last two values (a_{t-2}, a_{t-1}) = (low + xidx, low + yidx)
# Initialization at t=2: states (a_1 = low, a_2 = y)
dp = [[INF] * (R + 1) for _ in range(R + 1)]
# Possible a_2 values respecting monotonicity and step limit
max_y = min(low + max_step, high)
for y in range(low, max_y + 1):
    yidx = y - low
    base_cost = (low * low) + (y * y) - lambda_weight * (low * y)
    if base_cost < dp[0][yidx]:
        dp[0][yidx] = base_cost

# Forward DP for t = 3..n
for t in range(3, n + 1):
    dp2 = [[INF] * (R + 1) for _ in range(R + 1)]
    for xidx in range(R + 1):
        for yidx in range(R + 1):
            cur = dp[xidx][yidx]
            if cur == INF:
                continue
            x = low + xidx
            y = low + yidx
            # Next value z must satisfy y <= z <= min(y + max_step, high)
            max_z = y + max_step
            if max_z > high:
                max_z = high
            for z in range(y, max_z + 1):
                zidx = z - low
                # Incremental cost: add z^2 and subtract adjacent and lag-2 products
                new_cost = cur + (z * z) - lambda_weight * (y * z) - (x * z)
                if new_cost < dp2[yidx][zidx]:
                    dp2[yidx][zidx] = new_cost
    dp = dp2

# The last value must be exactly high
best = INF
for yidx in range(R + 1):
    c = dp[yidx][R]
    if c < best:
        best = c
if best == INF:
    # No valid sequence reaches high under constraints
    return False, None

answer = best
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

